from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class ArtifactsScenario(BaseScenario):
    name = 'artifacts'
    description = 'Artifact search and retrieval tools'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='search_artifacts_by_binder', tool='search_artifacts', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'min_length': 1, 'all_items_keys': ['id', 'artifact_type', 'created_by']}, description='Search artifacts by binder ID returns fixture data'), TestCase(name='search_artifacts_by_type_hypothesis', tool='search_artifacts', params={'binder_id': 'binder_001', 'artifact_type': 'hypothesis_artifact'}, expected={'is_array': True, 'error': False, 'array_length_range': [3, 3], 'all_items_field_equals': {'artifact_type': 'hypothesis_artifact'}}, description='Search hypothesis artifacts in binder_001 returns 3'), TestCase(name='search_artifacts_by_type_evidence', tool='search_artifacts', params={'binder_id': 'binder_001', 'artifact_type': 'evidence_artifact'}, expected={'is_array': True, 'error': False, 'array_length_range': [4, 4], 'all_items_field_equals': {'artifact_type': 'evidence_artifact'}}, description='Search evidence artifacts in binder_001 returns 4'), TestCase(name='search_artifacts_by_phase', tool='search_artifacts', params={'binder_id': 'binder_001', 'phase': 1}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Search artifacts filtered by phase 1'), TestCase(name='search_artifacts_by_function', tool='search_artifacts', params={'binder_id': 'binder_001', 'function_name': 'BoardReader::processData'}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Search artifacts by function name'), TestCase(name='search_artifacts_by_tags', tool='search_artifacts', params={'binder_id': 'binder_001', 'tags': 'timeout,network'}, expected={'is_array': True, 'error': False}, description='Search artifacts by tags'), TestCase(name='search_artifacts_include_deleted', tool='search_artifacts', params={'binder_id': 'binder_001', 'include_deleted': True}, expected={'is_array': True, 'error': False}, description='Search artifacts including deleted'), TestCase(name='search_artifacts_pagination', tool='search_artifacts', params={'binder_id': 'binder_001', 'limit': 5, 'offset': 0}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 5]}, description='Search artifacts with pagination'), TestCase(name='search_artifacts_empty_binder', tool='search_artifacts', params={'binder_id': 'nonexistent_binder'}, expected={'is_array': True, 'error': False}, description='Search artifacts for non-existent binder returns empty'), TestCase(name='get_artifact_existing', tool='get_artifact', params={'binder_id': 'binder_001', 'artifact_id': 'hyp_001'}, expected={'exact_values': {'id': 'hyp_001', 'artifact_type': 'hypothesis_artifact'}, 'contains_keys': ['description', 'created_by', 'source']}, description='Get existing artifact returns correct data'), TestCase(name='get_artifact_not_found', tool='get_artifact', params={'binder_id': 'binder_001', 'artifact_id': 'nonexistent'}, expected={'contains_keys': ['error']}, description='Get non-existent artifact returns error'), TestCase(name='get_artifact_history_existing', tool='get_artifact_history', params={'binder_id': 'binder_001', 'artifact_id': 'hyp_001'}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get history for artifact with modifications'), TestCase(name='get_artifact_history_not_found', tool='get_artifact_history', params={'binder_id': 'nonexistent', 'artifact_id': 'test_artifact'}, expected={'contains_keys': ['error']}, description='Get history for non-existent binder returns error'), TestCase(name='search_artifact_content_basic', tool='search_artifact_content', params={'binder_id': 'binder_001', 'query': 'timeout'}, expected={'is_array': True, 'error': False}, description="Full-text search for 'timeout' in artifact content"), TestCase(name='search_artifact_content_filtered', tool='search_artifact_content', params={'binder_id': 'binder_001', 'query': 'network', 'artifact_types': 'evidence_artifact'}, expected={'is_array': True, 'error': False}, description='Full-text search filtered by artifact type'), TestCase(name='search_artifact_content_no_results', tool='search_artifact_content', params={'binder_id': 'binder_001', 'query': 'xyznonexistentxyz'}, expected={'is_array': True, 'error': False}, description='Full-text search with no matches returns empty')]